"""1st People's Choice Awards (1975) — Favorite Movie / Movie of the Year: Favorite Motion Picture (1974 films) — runnable demo.
Database: The People's Choice Awards Database. Run: python3 demo.py (standard library only)."""
RECORD_ID = "JAH-PCA-000001"
DATA = {
  "1975": "1st People's Choice Awards — Favorite Motion Picture (1974 films)",
  "2013": "39th People's Choice Awards — Favorite Movie: The Hunger Games",
  "2015": "41st People's Choice Awards — Favorite Movie: Maleficent",
  "2018": "44th People's Choice Awards — Movie of 2018: Avengers: Infinity War",
  "2020": "46th People's Choice Awards — Movie of 2020: Bad Boys for Life",
  "2021": "47th People's Choice Awards — Movie of 2021: Black Widow",
  "2022": "48th People's Choice Awards — Movie of 2022: Top Gun: Maverick",
  "2024": "49th People's Choice Awards — Movie of the Year: Barbie",
  "2016": "42nd People's Choice Awards — Favorite Movie: Furious 7",
  "2017": "43rd People's Choice Awards — Favorite Movie: Finding Dory",
  "2019": "45th People's Choice Awards — Movie of 2019: Avengers: Endgame"
}

def lookup(key):
    """Return the ceremony and top winner for a given year."""
    return DATA.get(str(key), "No entry for %%s" %% key)

def all_keys():
    return sorted(DATA.keys())

def search(text):
    t = text.lower()
    return {k: v for k, v in DATA.items() if t in str(v).lower()}

if __name__ == "__main__":
    print("=" * 64)
    print(RECORD_ID)
    print("=" * 64)
    print("entries:", len(DATA))
    keys = all_keys()
    if keys:
        print("first:", keys[0], "->", lookup(keys[0]))
        print("last: ", keys[-1], "->", lookup(keys[-1]))

